	private static void assertPendingTableMatches(Event[] events) {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1L << 30);
		LmdbDirectAdjacencyCommitDelta delta = new LmdbDirectAdjacencyCommitDelta(account, 1L << 30);
		delta.begin(41);
		Set<Row> expectedRows = new HashSet<>();
		Set<Node> expectedNodes = new HashSet<>();

		for (int index = 0; index < events.length; index++) {
			Event event = events[index];
			if ((index & 1) == 0) {
				delta.recordAdd(event.subject, event.predicate, event.object, 0, event.explicit);
			} else {
				delta.recordRemove(event.subject, event.predicate, event.object, 0, event.explicit);
			}

			int outgoingPlane = event.explicit ? LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT
					: LmdbAdjacencyPlane.PLANE_OUTGOING_INFERRED;
			int incomingPlane = event.explicit ? LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT
					: LmdbAdjacencyPlane.PLANE_INCOMING_INFERRED;
			expectedRows.add(new Row(event.subject, outgoingPlane, event.predicate));
			expectedRows.add(new Row(event.object, incomingPlane, event.predicate));
			expectedNodes.add(new Node(event.subject, outgoingPlane));
			expectedNodes.add(new Node(event.object, incomingPlane));
		}

		SealedDirectDelta sealed = delta.seal(42);
		try {
			assertThat(sealed.isOverflowed()).isFalse();
			PendingTable pending = sealed.pendingTable();
			assertThat(pending).isNotNull();
			assertThat(pending.rowCount()).isEqualTo(expectedRows.size());
			for (Row row : expectedRows) {
				if (!pending.touches(row.rawKey, row.plane, row.rawPredicateId)) {
					throw new AssertionError("missing pending row: " + row);
				}
			}
			for (Node node : expectedNodes) {
				if (!pending.touchesNode(node.rawKey, node.plane)) {
					throw new AssertionError("missing pending node: " + node);
				}
			}
			assertAbsentRowsAndNodes(pending, expectedRows, expectedNodes);
		} finally {
			sealed.close();
		}
		assertThat(account.totalChargedBytes()).isZero();
	}

	private static Event[] events(int eventCount, Distribution distribution, long seed) {
		Event[] events = new Event[eventCount];
		SplittableRandom random = new SplittableRandom(seed);
		for (int event = 0; event < eventCount; event++) {
			events[event] = switch (distribution) {
			case FULL_WIDTH -> fullWidthEvent(events, event, random);
			case NARROW_IDS -> new Event(
					uri(1 + (event * 17L) % Math.max(32, eventCount / 4)),
					uri(100 + event % 64),
					uri(1_000_000 + (event * 31L) % Math.max(64, eventCount / 2)),
					(event & 1) == 0);
			case HOT_KEY -> new Event(
					uri(event % 8 == 0 ? 1 + event % 16 : 7),
					uri(100 + event % 32),
					uri(10_000 + event % 256),
					(event & 1) == 0);
			case ALREADY_ORDERED -> new Event(uri(1 + 2L * event), uri(100), uri(2 + 2L * event), true);
			case DUPLICATE_HEAVY -> new Event(
					UNSIGNED_BOUNDARIES[event & 3],
					UNSIGNED_BOUNDARIES[(event >>> 2) & 3],
					UNSIGNED_BOUNDARIES[(event >>> 4) & 3],
					(event & 1) == 0);
			};
		}
		return events;
	}

	private static Event fullWidthEvent(Event[] events, int event, SplittableRandom random) {
		if (event < UNSIGNED_BOUNDARIES.length) {
			return new Event(
					UNSIGNED_BOUNDARIES[event],
					UNSIGNED_BOUNDARIES[(event + 1) & 3],
					UNSIGNED_BOUNDARIES[3 - event],
					(event & 1) == 0);
		}
		if (event % 11 == 0) {
			return events[event - 1];
		}
		return new Event(random.nextLong(), random.nextLong(), random.nextLong(), (event & 1) == 0);
	}

	private static Event[] fuzzEvents(int eventCount, int domain, SplittableRandom random) {
		Event[] events = new Event[eventCount];
		for (int event = 0; event < eventCount; event++) {
			long subject = domain < 0 ? random.nextLong() : random.nextLong(domain);
			long object = domain < 0 ? random.nextLong() : random.nextLong(domain);
			long predicate = domain < 0 ? random.nextLong() : random.nextLong(Math.max(1, domain >>> 1));
			if ((event & 127) == 0) {
				subject = Long.MIN_VALUE;
			} else if ((event & 127) == 1) {
				object = -1;
			} else if ((event & 127) == 2) {
				predicate = Long.MAX_VALUE;
			}
			events[event] = new Event(subject, predicate, object, random.nextBoolean());
		}
		return events;
	}

	private static void assertAbsentRowsAndNodes(PendingTable pending, Set<Row> rows, Set<Node> nodes) {
		int firstPlane = LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT;
		int lastPlane = LmdbAdjacencyPlane.PLANE_INCOMING_INFERRED;
		for (int plane = firstPlane; plane <= lastPlane; plane++) {
			long rowKey = 0x243f6a8885a308d3L ^ plane;
			long predicate = 0x13198a2e03707344L;
			while (rows.contains(new Row(rowKey, plane, predicate))) {
				predicate++;
			}
			assertThat(pending.touches(rowKey, plane, predicate)).isFalse();

			long nodeKey = 0xa4093822299f31d0L ^ plane;
			while (nodes.contains(new Node(nodeKey, plane))) {
				nodeKey++;
			}
			assertThat(pending.touchesNode(nodeKey, plane)).isFalse();
		}
	}

